chain.ist:
Posizione_Asse_X:=MC_X.Act.Pos;
Posizione_Asse_Y:=MC_Y.Act.Pos;

X_Origin:=MC_X.DrvStatus.HomeSw;
X_Cw:=MC_X.DrvStatus.P_OT;
X_Ccw:=MC_X.DrvStatus.N_OT;

Y_Origin:=MC_Y.DrvStatus.HomeSw;
Y_Cw:=MC_Y.DrvStatus.P_OT;
Y_Ccw:=MC_Y.DrvStatus.N_OT;

X_Allarm_Code:=MC_X.MFaultLvl.Code;
Y_Allarm_Code:=MC_Y.MFaultLvl.Code;

(*Quote robot movimentazione da PRESA a DEPOSITO*)
(*MOV1 asse X*)
Distance1[0]:=(X_PRESA - 50);
Distance1[1]:=0;
(*MOV2 asse Y giù*)
Distance2[0]:=(Distance1[0]);
Distance2[1]:=(Y_PRESA);
(*MOV3 asse X aggancio*)
Distance3[0]:=(X_PRESA );
Distance3[1]:=Distance2[1];
(*MOV4A asse Y aggancio *)
Distance4_Acc[0]:=0;
Distance4_Acc[1]:=-50;(*mm di velocità bassa)
(*MOV4 asse Y salita con cesto*)
Distance4[0]:=Distance3[0];
Distance4[1]:=0;
(*MOV5 asse X con cesto*)
Distance5[0]:=(X_DEPOSITO );
Distance5[1]:=Distance4[1];
(*MOV6 asse Y deposito cesto*)
Distance6[0]:=(Distance5[0]);
Distance6[1]:=(Y_DEPOSITO-50);
(*MOV6A asse Y deposito cesto velocità bassa*)
Distance6_Dec[0]:=(Distance5[0]);
Distance6_Dec[1]:=(Y_DEPOSITO);
(*MOV7*)
Distance7[0]:=(X_DEPOSITO -50);
Distance7[1]:=Distance6_Dec[1];
(*MOV8*)
Distance8[0]:=(Distance7[0] );
Distance8[1]:=0;

;

Opr_F1.MVUpLmt:=100;
Opr_F1.Alpha:=0.65;
Opr_F1.ATCalcGain:=1;
Opr_F1.ATHystrs:=0.2;
Init_F1.SampTime:=time#100ms;
Init_F1.RngUpLmt:=100;
ProportionalBand_F1:=1;

Opr_F2.MVUpLmt:=100;
Opr_F2.Alpha:=0.65;
Opr_F2.ATCalcGain:=1;
Opr_F2.ATHystrs:=0.2;
Init_F2.SampTime:=time#100ms;
Init_F2.RngUpLmt:=100;
ProportionalBand_F2:=1;

FOR CH:=1 TO  10 DO;

	FOR N:=0 TO  15 DO;
	OutABit(SCADA[CH],N,Bit[(N+CH*100)]);
	END_FOR;

END_FOR;

//Default di 60FE.01=0 (ver. <= 1.1)
//Default di 60FE.01=1 (ver. > 1.1)

//60FE.01=0   60FE.02=0  -> Freno MANTENUTO (Asse NON cade)
//60FE.01=0   60FE.02=1	  -> Freno RILASCIATO (Asse cade)
//60FE.01=1   60FE.02=0   -> Freno MANTENUTO (Asse NON cade)
//60FE.01=1   60FE.02=1   -> Freno MANTENUTO (Asse NON cade)

//Mantenere 60FE.01 a 0 e Usare 60FE.02 per bloccare e sbloccare il freno


SDO_BrkSet.Index:=UINT#16#60FE;
SDO_BrkSet.Subindex:=USINT#16#01;
SDO_BrkSet.IsCompleteAccess:=FALSE;

SDO_Brk.Index:=UINT#16#60FE;
SDO_Brk.Subindex:=USINT#16#02;
SDO_Brk.IsCompleteAccess:=FALSE;

Data_BrkLock:=DWORD#16#0;
Data_BrkRel:=DWORD#16#1;
Data:=DWORD#16#0;

SDO_Restart.Index:=UINT#16#2400;
SDO_Restart.Subindex:=USINT#16#1;
SDO_Restart.IsCompleteAccess:=FALSE;

Data_Restart[0]:=BYTE#16#74;
Data_Restart[1]:=BYTE#16#65;
Data_Restart[2]:=BYTE#16#73;
Data_Restart[3]:=BYTE#16#65;
Data_Restart[4]:=BYTE#16#72;
Data_Restart[5]:=BYTE#16#61;

SDO_ErrCode.Index:=UINT#16#4000;
SDO_ErrCode.Subindex:=USINT#16#82;
SDO_ErrCode.IsCompleteAccess:=FALSE;

SDO_ErrSubCode.Index:=UINT#16#4000;
SDO_ErrSubCode.Subindex:=USINT#16#81;
SDO_ErrSubCode.IsCompleteAccess:=FALSE;

CASE (WORD_TO_UINT (Data_ErrCode AND WORD#16#00F0)) OF
	160:
		IF (WORD_TO_INT(Data_ErrCode AND WORD#16#000F))<10 THEN			
				Warning:=CONCAT ('A',INT_TO_STRING(WORD_TO_INT(Data_ErrCode AND WORD#16#000F)));
		ELSIF (Data_ErrCode AND WORD#16#000F)=WORD#16#B THEN
				Warning:='AB';
		ELSE
			ClearString (Warning);
			END_IF;
		ClearString (Errore);
	176:
		IF (WORD_TO_INT(Data_ErrCode AND WORD#16#000F))<10 THEN
			Warning:=CONCAT ('B',INT_TO_STRING(WORD_TO_INT(Data_ErrCode AND WORD#16#000F)));
		ELSE
			ClearString(Warning);
		END_IF;
		ClearString (Errore);
ELSE
	IF BCD_TO_UINT (Data_ErrCode AND WORD#16#00FF) <> 0 THEN
		Errore:=UINT_TO_STRING(BCD_TO_UINT (Data_ErrCode AND WORD#16#00FF));
	ELSE
		ClearString (Errore);
	END_IF;
	ClearString(Warning);
END_CASE;

Numero_Subcode:=DWORD_TO_UINT (Data_ErrSubCode AND DWORD#16#000000FF);
IF Numero_Subcode>9 THEN
	Numero_Subcode:=UINT#0;
END_IF;

IF Errore<>'' THEN
	Errore:=CONCAT (Errore,'.',UINT_TO_STRING(Numero_Subcode));
END_IF;
 
 IF Warning<>'' THEN
	Warning:=CONCAT (Warning,'.',UINT_TO_STRING(Numero_Subcode));
 END_IF;
